CREATE TABLE knowledge_observations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),file_id TEXT REFERENCES files(id),unit_id TEXT REFERENCES knowledge_units(id),evidence_id TEXT REFERENCES evidence_items(id),namespace TEXT NOT NULL CHECK(namespace IN ('literature','project','guidance')),intent TEXT NOT NULL,source_version TEXT NOT NULL,text TEXT NOT NULL,locator_json TEXT NOT NULL,metadata_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,content_hash));
CREATE INDEX knowledge_observations_file ON knowledge_observations(project_id,file_id);
CREATE TABLE kg_entities(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),namespace TEXT NOT NULL,entity_key TEXT NOT NULL,kind TEXT NOT NULL,current_version_id TEXT,redirect_id TEXT REFERENCES kg_entities(id),created_at TEXT NOT NULL,UNIQUE(project_id,namespace,entity_key));
CREATE TABLE kg_entity_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),entity_id TEXT NOT NULL REFERENCES kg_entities(id),parent_id TEXT REFERENCES kg_entity_versions(id),name TEXT NOT NULL,description TEXT NOT NULL,content_hash TEXT NOT NULL,method TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX kg_entity_versions_parent ON kg_entity_versions(entity_id,created_at);
CREATE TABLE kg_aliases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),entity_id TEXT NOT NULL REFERENCES kg_entities(id),alias TEXT NOT NULL,normalized TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'candidate',decision_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,UNIQUE(entity_id,normalized));
CREATE INDEX kg_alias_lookup ON kg_aliases(project_id,normalized);
CREATE TABLE kg_assertions(claim_version_id TEXT PRIMARY KEY REFERENCES claim_versions(id),project_id TEXT NOT NULL REFERENCES projects(id),namespace TEXT NOT NULL,subject_id TEXT REFERENCES kg_entities(id),predicate TEXT NOT NULL,object_id TEXT REFERENCES kg_entities(id),object_json TEXT NOT NULL,attribution TEXT NOT NULL,conditions_json TEXT NOT NULL,polarity TEXT NOT NULL,modality TEXT NOT NULL,method TEXT NOT NULL,lifecycle TEXT NOT NULL DEFAULT 'candidate',content_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX kg_assertions_subject ON kg_assertions(project_id,subject_id,object_id,lifecycle);
CREATE TABLE kg_support_assessments(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),claim_version_id TEXT NOT NULL REFERENCES kg_assertions(claim_version_id),evidence_id TEXT REFERENCES evidence_items(id),observation_id TEXT REFERENCES knowledge_observations(id),source_version TEXT NOT NULL,support TEXT NOT NULL CHECK(support IN ('supported','partial','contradicted','insufficient','not_checked')),quote TEXT NOT NULL,conditions_json TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN ('human','model')),reviewer TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX kg_support_claim ON kg_support_assessments(claim_version_id,created_at);
CREATE TABLE wiki_pages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),namespace TEXT NOT NULL,kind TEXT NOT NULL,slug TEXT NOT NULL,title TEXT NOT NULL,current_version_id TEXT,created_at TEXT NOT NULL,UNIQUE(project_id,namespace,slug));
CREATE TABLE wiki_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),page_id TEXT NOT NULL REFERENCES wiki_pages(id),parent_id TEXT REFERENCES wiki_versions(id),content_hash TEXT NOT NULL,schema_version TEXT NOT NULL,author TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'candidate',created_at TEXT NOT NULL);
CREATE TABLE wiki_blocks(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES wiki_versions(id),block_key TEXT NOT NULL,kind TEXT NOT NULL,text TEXT NOT NULL,author TEXT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',position INTEGER NOT NULL,UNIQUE(version_id,block_key));
CREATE TABLE wiki_links(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),block_id TEXT NOT NULL REFERENCES wiki_blocks(id),target_type TEXT NOT NULL,target_id TEXT NOT NULL,target_version TEXT NOT NULL,relation TEXT NOT NULL,UNIQUE(block_id,target_type,target_id,target_version,relation));
CREATE INDEX wiki_links_target ON wiki_links(project_id,target_type,target_id);
CREATE TABLE knowledge_dependencies(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),downstream_type TEXT NOT NULL,downstream_id TEXT NOT NULL,downstream_version TEXT NOT NULL,upstream_type TEXT NOT NULL,upstream_id TEXT NOT NULL,upstream_version TEXT NOT NULL,relation TEXT NOT NULL DEFAULT 'derived_from',UNIQUE(project_id,downstream_type,downstream_id,upstream_type,upstream_id,upstream_version));
CREATE INDEX knowledge_dependencies_upstream ON knowledge_dependencies(project_id,upstream_type,upstream_id);
CREATE INDEX knowledge_dependencies_downstream ON knowledge_dependencies(project_id,downstream_type,downstream_id);
CREATE TABLE knowledge_events(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,note TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,result_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,processed_at TEXT);
CREATE TABLE knowledge_build_items(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT NOT NULL REFERENCES tasks(id),item_key TEXT NOT NULL,input_hash TEXT NOT NULL,stage TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT NOT NULL DEFAULT '{}',error TEXT,updated_at TEXT NOT NULL,UNIQUE(project_id,item_key,input_hash));
CREATE INDEX knowledge_build_tasks ON knowledge_build_items(task_id,status);
CREATE TABLE knowledge_releases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),parent_id TEXT REFERENCES knowledge_releases(id),manifest_json TEXT NOT NULL,content_hash TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE knowledge_artifacts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT REFERENCES tasks(id),kind TEXT NOT NULL,content_hash TEXT NOT NULL,path TEXT NOT NULL,manifest_json TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE knowledge_evaluation_cases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),category TEXT NOT NULL,question TEXT NOT NULL,gold_json TEXT NOT NULL DEFAULT '{}',state TEXT NOT NULL DEFAULT 'unlabelled',created_at TEXT NOT NULL);
CREATE TABLE knowledge_comparisons(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT REFERENCES tasks(id),manifest_json TEXT NOT NULL,result_json TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL);
